import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.vLhlLNVn.js";const l=JSON.parse('{"title":"How do existing ESPHome projects fit the adapter?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/05.hintergrund/02.esphome-projekte.md"},"headers":[],"relativePath":"adapter/esphome/hintergrund/esphome-projekte.md","filePath":"adapter/esphome/hintergrund/esphome-projekte.md","lastUpdated":1795571670000}'),r={name:"adapter/esphome/hintergrund/esphome-projekte.md"};function d(n,e,i,h,p,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="how-do-existing-esphome-projects-fit-the-adapter" tabindex="-1">How do existing ESPHome projects fit the adapter? <a class="header-anchor" href="#how-do-existing-esphome-projects-fit-the-adapter" aria-label="Permalink to &quot;How do existing ESPHome projects fit the adapter?&quot;">​</a></h1><p><a id="custom-components-existing-esphome-projects"></a></p><h2 id="do-custom-components-and-existing-esphome-projects-work-with-the-adapter" tabindex="-1">Do custom components and existing ESPHome projects work with the adapter? <a class="header-anchor" href="#do-custom-components-and-existing-esphome-projects-work-with-the-adapter" aria-label="Permalink to &quot;Do custom components and existing ESPHome projects work with the adapter?&quot;">​</a></h2><p>Yes, as long as the firmware reports its values as entities over the API. Where an entity comes from, ESPHome itself, an external component or a ready-made project, does not matter to the adapter.</p><p>The adapter knows these types: sensor, binary sensor, text sensor, switch, number, text, select, button, lock, cover, fan, light and climate. If a device reports another type, the log shows <code>DeviceType &lt;type&gt; not yet supported</code> with the details once, and this type gets no values.</p><p>If a component delivers a JSON text, it arrives as one text state. Split it in a script with <code>JSON.parse</code>. Existing YAML files usually work unchanged in the dashboard of the adapter.</p><p><a id="use-esphome-over-mqtt-instead"></a></p><h2 id="can-i-use-esphome-over-mqtt-instead-of-or-alongside-the-adapter" tabindex="-1">Can I use ESPHome over MQTT instead of or alongside the adapter? <a class="header-anchor" href="#can-i-use-esphome-over-mqtt-instead-of-or-alongside-the-adapter" aria-label="Permalink to &quot;Can I use ESPHome over MQTT instead of or alongside the adapter?&quot;">​</a></h2><p>Both work. The adapter only uses the Native API, <code>api:</code> and <code>mqtt:</code> may be in the YAML together. The MQTT values then come in additionally via an MQTT adapter, usually as text such as <code>ON</code> and <code>OFF</code>.</p><p>If you only use MQTT, you do not need this adapter. Then leave <code>api:</code> out of the YAML. With <code>api:</code> a device restarts after 15 minutes without an API connection unless you set <code>reboot_timeout</code> to <code>0s</code>.</p><p><a id="manage-bluetooth-proxy-adapter-dashboard"></a></p><h2 id="can-i-manage-a-bluetooth-proxy-with-the-adapter-and-dashboard" tabindex="-1">Can I manage a Bluetooth proxy with the adapter and dashboard? <a class="header-anchor" href="#can-i-manage-a-bluetooth-proxy-with-the-adapter-and-dashboard" aria-label="Permalink to &quot;Can I manage a Bluetooth proxy with the adapter and dashboard?&quot;">​</a></h2><p>You add a Bluetooth proxy to the adapter like any device. The adapter shows its normal entities, e.g. sensors and buttons. It does not use the proxy function itself, which is meant for Home Assistant.</p><p>A pre-flashed proxy appears in the dashboard of the adapter with &quot;Adopt&quot; if the dashboard finds it on the network. The dashboard then creates a YAML, and you manage and update it there.</p>',14)])])}const u=t(r,[["render",d]]);export{l as __pageData,u as default};
